<?php
require __DIR__.'/api/auth.php';
$token=(string)($_GET['token']??$_POST['token']??'');
function attach_pending_registration(int $userId,string $email,string $token): bool { if($token==='')return false;$hash=hash('sha256',$token);$s=db()->prepare('SELECT id FROM registrations WHERE activation_token_hash=? AND activation_expires_at>NOW() AND user_id IS NULL AND email=?');$s->execute([$hash,$email]);$id=$s->fetchColumn();if(!$id)return false;$s=db()->prepare('UPDATE registrations SET user_id=?,activation_token_hash=NULL,activation_expires_at=NULL WHERE id=?');$s->execute([$userId,$id]);return true; }
$current=current_user();if($current){attach_pending_registration((int)$current['id'],(string)$current['email'],$token);header('Location: /dashboard.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['username']??''));$pass=(string)($_POST['password']??'');$s=db()->prepare('SELECT * FROM users WHERE username=? AND active=1');$s->execute([$name]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];attach_pending_registration((int)$u['id'],(string)$u['email'],$token);header('Location: /dashboard.php');exit;}$error='Invalid username or password / Nieprawidłowy login lub hasło';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in — SPECTECHNOLOGY</title><link rel="stylesheet" href="/assets/site-v13.css"><link rel="stylesheet" href="/assets/portal.css"></head><body class="portal"><main class="auth-card"><a href="/" class="portal-logo"><img src="/noBgColor-dark.png" alt="SPECTECHNOLOGY"></a><p class="eyebrow">CLIENT & PARTNER PORTAL</p><h1>Sign in / Zaloguj się</h1><?php if($token):?><p>Sign in to add the new application to your existing account.<br>Zaloguj się, aby dodać nowe zgłoszenie do istniejącego konta.</p><?php endif?><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="token" value="<?=e($token)?>"><label>Username / Login<input name="username" autocomplete="username" required></label><label>Password / Hasło<input type="password" name="password" autocomplete="current-password" required></label><button class="primary" type="submit">Sign in / Zaloguj się</button></form><a href="/">← Main page / Strona główna</a></main></body></html>